//! Group-filter presentation is generated by the service, never regrouped in the UI.
use super::*;
use crate::service::{LaunchSort, LaunchSortColumn, LaunchTableContent, SortDirection};
fn project(
    fixture: &Fixture,
    id: u64,
    name: &str,
    group: u64,
    ports: &[u16],
) -> crate::model::Project {
    let path = fixture.0.join(format!("project-{id}"));
    fs::create_dir_all(&path).unwrap();
    let mut scripts = Vec::new();
    for (index, port) in ports.iter().enumerate() {
        let mut script = fixture.script("echo unused\n");
        script.id = id * 10 + index as u64;
        script.name = format!("launch-{index}");
        script.expected_port = Some(*port);
        script.cwd = path.clone();
        scripts.push(script);
    }
    crate::model::Project {
        id,
        name: name.into(),
        display_name: None,
        path,
        group,
        favorite: false,
        scripts,
        explicit_scripts: true,
        description: String::new(),
    }
}
fn service(fixture: &Fixture) -> Service {
    let mut service = api_service(fixture);
    service.catalog.groups.push(crate::model::Group {
        id: 2,
        name: "Other".into(),
    });
    service.catalog.projects = vec![
        project(fixture, 10, "Alpha", 1, &[9000, 7000]),
        project(fixture, 11, "Beta", 1, &[5000, 1000]),
        project(fixture, 12, "Empty", 1, &[]),
        project(fixture, 13, "Other", 2, &[3000]),
    ];
    service
}
#[test]
fn filtered_group_has_one_title_per_project_and_no_placeholder_launch_for_empty_projects() {
    let fixture = Fixture::new();
    let service = service(&fixture);
    let LaunchTableContent::Projects(sections) = service
        .launch_table_content(Filter::All, "", LaunchSort::default(), Some(1))
        .unwrap()
    else {
        panic!("expected project sections")
    };
    assert_eq!(
        sections.iter().map(|p| p.project_id).collect::<Vec<_>>(),
        vec![10, 11, 12]
    );
    assert_eq!(
        sections.iter().map(|p| p.rows.len()).collect::<Vec<_>>(),
        vec![2, 2, 0]
    );
    for section in sections {
        assert!(
            section
                .rows
                .iter()
                .all(|row| row.project_id == section.project_id
                    && row.group.id == 1
                    && row.script.is_some())
        );
    }
    let LaunchTableContent::Flat(rows) = service
        .launch_table_content(Filter::All, "", LaunchSort::default(), None)
        .unwrap()
    else {
        panic!("all projects must stay flat")
    };
    assert_eq!(rows.len(), 6);
    assert!(
        rows.iter()
            .any(|row| row.project_id == 12 && row.script.is_none())
    );
}
#[test]
fn filtered_sort_keeps_project_sections_contiguous_and_sorts_launches_within_them() {
    let fixture = Fixture::new();
    let service = service(&fixture);
    for (direction, expected) in [
        (
            SortDirection::Ascending,
            vec![vec![7000, 9000], vec![1000, 5000]],
        ),
        (
            SortDirection::Descending,
            vec![vec![9000, 7000], vec![5000, 1000]],
        ),
    ] {
        let sort = LaunchSort {
            column: LaunchSortColumn::Port,
            direction,
        };
        let LaunchTableContent::Projects(sections) = service
            .launch_table_content(Filter::All, "", sort, Some(1))
            .unwrap()
        else {
            panic!("expected sections")
        };
        assert_eq!(
            sections.iter().map(|p| p.project_id).collect::<Vec<_>>(),
            vec![10, 11, 12]
        );
        let ports: Vec<Vec<u16>> = sections
            .iter()
            .take(2)
            .map(|section| {
                section
                    .rows
                    .iter()
                    .map(|row| row.script.as_ref().unwrap().expected_port.unwrap())
                    .collect()
            })
            .collect();
        assert_eq!(ports, expected);
    }
    let sort = LaunchSort {
        column: LaunchSortColumn::Project,
        direction: SortDirection::Descending,
    };
    let LaunchTableContent::Projects(sections) = service
        .launch_table_content(Filter::All, "", sort, Some(1))
        .unwrap()
    else {
        panic!("expected sections")
    };
    assert_eq!(
        sections
            .iter()
            .map(|p| p.project_name.as_str())
            .collect::<Vec<_>>(),
        vec!["Empty", "Beta", "Alpha"]
    );
}
#[test]
fn project_identity_search_and_favorites_do_not_collapse_or_duplicate_sections() {
    let fixture = Fixture::new();
    let mut service = service(&fixture);
    service.catalog.projects[1].display_name = Some("Alpha".into());
    service.catalog.projects[1].scripts[1].name = "unique-launch".into();
    service.catalog.projects[1].scripts[1].favorite = true;
    let LaunchTableContent::Projects(sections) = service
        .launch_table_content(Filter::All, "Alpha", LaunchSort::default(), Some(1))
        .unwrap()
    else {
        panic!("expected sections")
    };
    assert_eq!(sections.len(), 2);
    assert_ne!(sections[0].project_id, sections[1].project_id);
    let LaunchTableContent::Projects(sections) = service
        .launch_table_content(Filter::All, "unique-launch", LaunchSort::default(), Some(1))
        .unwrap()
    else {
        panic!("expected sections")
    };
    assert_eq!(sections.len(), 1);
    assert_eq!(sections[0].project_id, 11);
    assert_eq!(sections[0].rows.len(), 1);
    let LaunchTableContent::Flat(rows) = service
        .launch_table_content(Filter::Favorites, "", LaunchSort::default(), None)
        .unwrap()
    else {
        panic!("favorites must stay flat")
    };
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].project_id, 11);
}
